package com.tanerinal.education.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.tanerinal.education.domain.PaymentView;import com.tanerinal.education.mapper.ShopOrderMapper;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class PaymentNotificationService{private final ShopOrderMapper orders;private final ObjectMapper mapper;private final String secret;private final PaymentEventPipeline events;public PaymentNotificationService(ShopOrderMapper o,ObjectMapper m,@Value("${education.payment-platform.callback-secret:demo-platform-callback-secret}")String s,PaymentEventPipeline e){orders=o;mapper=m;secret=s;events=e;}@Transactional public Result accept(String raw,String sig){if(!valid(raw,sig))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"INVALID_CALLBACK_SIGNATURE");try{Notice n=mapper.readValue(raw,Notice.class);PaymentView p=orders.lockPaymentByTransaction(n.channelTransactionNo()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"PAYMENT_NOT_FOUND"));String d=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));if(p.getAmount().compareTo(n.amount())!=0||!p.getCurrency().equals(n.currency())){orders.insertNotification(p.getId(),n.channel(),n.notificationId(),n.channelTransactionNo(),"REJECTED",d,"Amount or currency mismatch",n.status());return new Result("REJECTED");}String target=switch(n.status()){case "SUCCESS"->"SUCCESS";case "FAILED","CLOSED","EXPIRED"->n.status();default->"PENDING";};if("PENDING".equals(target))return new Result("IGNORED");int changed=orders.finishPayment(p.getId(),target,n.failureReason()==null?"":n.failureReason());if(changed==1){orders.insertPaymentEvent(p.getId(),UUID.randomUUID().toString(),"CALLBACK_"+target,"PENDING",target,"Signed asynchronous notification");if("SUCCESS".equals(target)&&orders.updateStatus(p.getOrderId(),"PENDING_PAYMENT","PAID")==1)orders.insertEvent(p.getOrderId(),orders.orderCustomerId(p.getOrderId()),"PAYMENT_SUCCEEDED","PENDING_PAYMENT","PAID","Signed asynchronous notification applied");events.append(p.getId().toString(),"PAYMENT_CALLBACK_"+target,raw);}orders.insertNotification(p.getId(),n.channel(),n.notificationId(),n.channelTransactionNo(),changed==1?"PROCESSED":"DUPLICATE_OR_FINAL",d,"",n.status());return new Result(changed==1?"PROCESSED":"ACKNOWLEDGED");}catch(DuplicateKeyException e){return new Result("ACKNOWLEDGED");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}private boolean valid(String raw,String sig){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return sig!=null&&MessageDigest.isEqual(m.doFinal(raw.getBytes(StandardCharsets.UTF_8)),Base64.getDecoder().decode(sig));}catch(Exception e){return false;}}public record Notice(String notificationId,String channelTransactionNo,String channel,String status,BigDecimal amount,String currency,String failureReason){}public record Result(String result){}}
